SELECT theme_name, sector_name_ja, COUNT(DISTINCT ticker) AS companies, ROUND(AVG(CASE WHEN operating_margin BETWEEN -1 AND 1 THEN operating_margin END) * 100, 1) AS avg_operating_margin_pct
FROM m_theme
GROUP BY theme_name, sector_name_ja
HAVING COUNT(DISTINCT ticker) >= {{min_companies}}
ORDER BY avg_operating_margin_pct DESC, theme_name
LIMIT {{top_n}}

SELECT sec_code4, name, industry, fiscal_year, net_sales, operating_income, ROUND(operating_margin * 100, 1) AS operating_margin_pct, ROUND(sales_growth * 100, 1) AS sales_growth_pct
FROM m_theme
WHERE theme_name = {{theme_name}}
ORDER BY net_sales DESC, sec_code4
LIMIT {{top_n}}

SELECT theme_name, sector_name_ja, SUM(signal_count) AS signals, SUM(CASE WHEN direction = 'bullish' THEN signal_count ELSE 0 END) AS bullish, SUM(CASE WHEN direction = 'bearish' THEN signal_count ELSE 0 END) AS bearish
FROM m_theme_signal
WHERE days_before_latest < {{days}}
GROUP BY theme_name, sector_name_ja
ORDER BY signals DESC, theme_name
LIMIT {{top_n}}
